namespace ProjectTower.particles.particles.glows;
public class GuideDoorBit : BaseParticle
{
public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
{
p.frame = 0.5f;
p.size = size;
p.loc = loc;
p.traj = traj;
p.flags = Rand.GetRandomInt(41, 50);
p.rDir = Rand.GetRandomFloat(-1f, 1f) * 10f;
p.owner = owner;
base.Init(p, loc, traj, size, rotation, flags, owner);
}
public override void Update(Particle p, float frameTime)
{
p.rotation += p.rDir * frameTime;
base.Update(p, frameTime);
}
public override void Draw(Particle p, float brite)
{
Vector2 screenLoc = ScrollManager.GetScreenLoc(p.loc, 0);
Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, p.flags, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.5f, p.rotation, 1f, 1f, 1f, p.frame);
Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, 0, new Vector2(1f, 0.1f) * ScrollManager.cannedDepth[0] * p.size, p.rotation, 1f, 1f, 1f, p.frame);
base.Draw(p, brite);
}
}
=== 3 JumpGlow.cs
namespace ProjectTower.particles.particles.glows;
public class JumpGlow : BaseParticle
{
public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
{
p.frame = Rand.GetRandomFloat(0.5f, 1f);
p.size = size;
p.loc = loc;
p.traj = traj;
p.rotation = rotation;
p.rDir = 0f;
p.aux = flags;
p.flags = Rand.GetRandomInt(16, 19);
p.rotation = Trig.GetAngle(p.traj, default);
p.owner = owner;
base.Init(p, loc, traj, size, rotation, flags, owner);
}
public override void Update(Particle p, float frameTime)
{
float frame = p.frame;
if (p.rDir < 1f)
{
p.rDir += frameTime * 10f;
if (p.rDir > 1f)
{
p.rDir = 1f;
}
}
base.Update(p, frameTime);
if (p.exists && (int)(p.frame * 7f) != (int)(frame * 7f))
{
p.traj *= 0.5f;
}
}
public override void Draw(Particle p, float brite)
{
float rDir = p.rDir;
rDir *= p.frame;
float g = 0.3f;
float b = 1f;
if (p.aux <= 1)
{
g = 0f;
b = 0f;
}
if (p.aux == 10)
{
g = 1f;
b = 1f;
}
Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.flags, new Vector2(1f, 0.1f) * p.size * ScrollManager.cannedDepth[0], p.rotation, 1f, g, b, rDir * 2f);
if (p.rDir < 0.5f)
{
Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), 0, new Vector2(1.2f, 0.4f) * p.size * ScrollManager.cannedDepth[0], p.rotation, 1f, 1f, 1f, (p.rDir < 0.1f) ? (p.rDir / 0.1f) : ((0.5f - p.rDir) / 0.4f));
}
base.Draw(p, brite);
}
}
=== 4 NightmareScreamBit.cs
namespace ProjectTower.particles.particles.glows;
public class NightmareScreamBit : BaseParticle
{
public const int REFRACT = 0;
public const int SUBTRACT = 1;
public const int ADD = 2;
public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
{
p.frame = 0.5f;
p.size = Rand.GetRandomFloat(1f, 3f);
p.loc = loc;
p.traj = traj;
p.rotation = rotation;
p.rDir = 0f;
p.aux = flags;
p.flags = Rand.GetRandomInt(41, 50);
base.Init(p, loc, traj, size, rotation, flags, owner);
}
public override void Update(Particle p, float frameTime)
{
float frame = p.frame;
base.Update(p, frameTime);
if (p.exists && (int)(p.frame * 10f) != (int)(frame * 10f))
{
p.traj *= 0.5f;
}
}
public override void Draw(Particle p, float brite)
{
Vector2 vector = new Vector2(p.frame * 4f + 0.5f, 0.5f);
float r = 1f;
float g = 1f;
float b = 1f;
Vector2 loc = p.loc;
switch (p.aux)
{
case 0:
r = 0f;
b = 0f;
vector.Y *= 2f;
loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 100f;
break;
case 1:
r = 0.5f;
g = 0.5f;
b = 0.5f;
break;
case 2:
r = 0.5f;
g = 0.45f;
b = 0.4f;
vector.Y = 0.1f;
break;
}
Vector2 screenLoc = ScrollManager.GetScreenLoc(loc, 0);
Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, p.flags, vector * ScrollManager.cannedDepth[0], p.rotation, r, g, b, p.frame * 6f);
base.Draw(p, brite);
}
}
=== 5 NightmareScreamFarm.cs
namespace ProjectTower.particles.particles.glows;
public class NightmareScreamFarm : BaseParticle
{
public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
{
p.frame = 1f;
p.size = Rand.GetRandomFloat(1f, 3f);
p.loc = loc;
p.traj = default;
p.rotation = rotation;
p.rDir = 0f;
p.owner = owner;
base.Init(p, loc, traj, size, rotation, flags, owner);
}
public override void Update(Particle p, float frameTime)
{
float frame = p.frame;
base.Update(p, frameTime);
if (p.exists)
{
if ((int)(p.frame * 10f) != (int)(frame * 10f))
{
HitManager.CheckHit(p);
}
if ((int)(p.frame * 60f) != (int)(frame * 60f))
{
float num = 0.025f;
float randomFloat = Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
Vector2 vector = new Vector2((float)Math.Cos(randomFloat), (float)Math.Sin(randomFloat)) * 2500f;
ParticleManager.AddBackRefractParticle(155, p.loc + vector * num, vector, 1f, randomFloat, 0, p.owner);
randomFloat = Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
vector = new Vector2((float)Math.Cos(randomFloat), (float)Math.Sin(randomFloat)) * 2500f;
ParticleManager.AddSubtractiveParticle(155, p.loc + vector * num, vector, 1f, randomFloat, 1, p.owner);
randomFloat = Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
vector = new Vector2((float)Math.Cos(randomFloat), (float)Math.Sin(randomFloat)) * 2500f;
ParticleManager.AddBackAdditiveParticle(155, p.loc + vector * num, vector, 1f, randomFloat, 2, p.owner);
}
QuakeManager.SetQuake(0.25f, p.loc);
}
}
public override void Draw(Particle p, float brite)
{
base.Draw(p, brite);
}
}
